    const YCD = $("#senior".concat(i)).length ? +$("#senior".concat(i)).html() : 0;
    let ADT = +$("#adult".concat(i)).html();
    const YTH = $("#young".concat(i)).length ? +$("#young".concat(i)).html() : 0;
    const BNN = $("#teenager".concat(i)).length ? +$("#teenager".concat(i)).html() : 0;
    let depDay;
    let arrDay;
    let BEGIN_DAY_01;
    let BEGIN_MONTH_01;
    let BEGIN_YEAR_01;
    let END_DAY_01;
    let END_MONTH_01;
    let END_YEAR_01;
