/**
 * Habilita la activación de checkboxes con la tecla Enter.
 * 
 * @param {string} selector 
 */
function enableCheckboxActivationWithEnter() {
  let selector = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : 'input[type="checkbox"]';
  document.querySelectorAll(selector).forEach(checkbox => {
    checkbox.addEventListener('keydown', event => {
      if (event.key === 'Enter') {
        event.preventDefault();
        checkbox.checked = !checkbox.checked; // Cambia el estado del checkbox
        checkbox.dispatchEvent(new Event('change'));
        checkbox.dispatchEvent(new Event('click'));
      }
    });
  });
}

